|massage envy|7-eleven|pingo doce|continente|well'?s|multi?opticas|instituto das sobrancelhas|dr.? well|todeschini|dell ?anno|florense|italinea|favorita m[oó]veis|ornare|solar ?prime|portal solar|blue ?sol|rentokil|carglass|auto ?glass|jet oil|dr.? lava/i.test($json.nome) }}","rightValue":"","operator":{"type":"boolean","operation":"false","singleValue":true}}]},"options":{}}},{"id":"c5e2bc67-88ff-4d45-919b-9756fe8b35de","name":"Não está na planilha","type":"n8n-nodes-base.filter","typeVersion":2.2,"position":[3300,100],"parameters":{"conditions":{"options":{"caseSensitive":true,"leftValue":"","typeValidation":"strict"},"combinator":"and","conditions":[{"id":"dup","leftValue":"={{ $('Ler leads existentes').all().some(linha => linha.json.place_id === $json.place_id) }}","rightValue":"","operator":{"type":"boolean","operation":"false","singleValue":true}}]},"options":{}}},{"id":"39fd3adb-d608-4003-ba5c-7a8f66a2c0ee","name":"Gemini: classificar e checar na web","type":"n8n-nodes-base.httpRequest","typeVersion":4.4,"retryOnFail":false,"maxTries":3,"waitBetweenTries":5000,"position":[3520,260],"parameters":{"method":"POST","url":"http://luna-workflows:8766/inferir","authentication":"genericCredentialType","genericAuthType":"httpHeaderAuth","sendBody":true,"bodyParameters":{"parameters":[{"name":"tarefa","value":"classificar"},{"name":"prompt","value":"=Negócio encontrado no Google Maps:
