{{ ($json.reviews ?? []).map(r => '- ' + (r.rating ?? '?') + ' estrelas: ' + (r.text?.text ?? r.originalText?.text ?? '')).join('\n') || '(nenhuma avaliação em texto)' }}

Escreva um briefing para o designer que vai criar o primeiro site deste negócio. Não copie frases das avaliações entre aspas e não cite nomes de clientes. Use exatamente estas três seções, em português, texto curto:

Elogiam: o que os clientes elogiam (ambiente, atendimento, profissionais citados pelo nome, estrutura, resultados).
Reclamam: o que reclamam. Se não houver reclamação, escreva "nada relevante nas avaliações".
Palavras deles: de 5 a 10 palavras ou expressões curtas que os próprios clientes usam para descrever o lugar, separadas por vírgula.

Se não houver avaliação em texto, responda apenas: Sem avaliações em texto para resumir."}]},"options":{"timeout":180000,"batching":{"batch":{"batchSize":1,"batchInterval":200}}}},"credentials":{"httpHeaderAuth":{"id":"REDACTED_CREDENTIAL_ID","name":"CONFIGURAR_MANUALMENTE"}},"notes":"Luna do Hermes (gpt-6-luna-900k). Nome preservado para os vínculos do fluxo. Sem envio ou ferramentas de escrita."},{"id":"7175487b-6b70-4ba9-838a-42ff84c5a4be","name":"Juntar lead + briefing","type":"n8n-nodes-base.merge","typeVersion":3.2,"position":[4620,100],"parameters":{"mode":"combine","combineBy":"combineByPosition","options":{}}},{"id":"2c5e7939-d99c-4824-b815-c229f5ce783d","name":"Montar lead","type":"n8n-nodes-base.code","typeVersion":2,"position":[4840,100],"parameters":{"mode":"runOnceForAllItems","language":"javaScript","jsCode":"// Único nó que monta o lead. Daqui em diante a esteira usa só $json.
const agora = $now.toISO();

function slugify(texto) {
  return String(texto ?? '')
    .toLowerCase()
    .normalize('NFD')
    .replace(/[̀-ͯ]/g, '')
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-+|-+$/g, '');
}

// Reserva para quando o Google não manda addressComponents
// "R. São Pedro, 119 - Muquiçaba, Guarapari - ES, 29215-200" -> "Guarapari"
function cidadeDoEndereco(endereco) {
  const m = String(endereco ?? '').match(/([^,]+?)(?:\s+-\s+|,\s*)[A-Z]{2}(?:,|$)/);
  return m ? m[1].split(' - ').pop().trim() : '';
}

// "https://www.instagram.com/studiofit/" -> "@studiofit"
function instagramDoLink(link) {
  const m = String(link ?? '').match(/instagram\.com\/([A-Za-z0-9._]+)/i);
  return m && !['p', 'reel', 'reels', 'stories', 'explore'].includes(m[1].toLowerCase()) ? '@' + m[1] : '';
}

function lerClassificacao(texto) {
  const s = String(texto ?? '');
  try {
    return JSON.parse(s.slice(s.indexOf('{'), s.lastIndexOf('}') + 1));
  } catch (e) {
    return {};
  }
}

// Slugs que já têm pasta: dois negócios com o mesmo nome não podem dividir pasta no Drive
const slugsEmUso = new Set();
for (const linha of $('Ler leads existentes').all()) {
  if (linha.json.nome) slugsEmUso.add(slugify(linha.json.nome));
  if (linha.json.vercel_project) slugsEmUso.add(String(linha.json.vercel_project).replace(/^demo-/, ''));
}

const vistos = new Set();
const leads = [];

for (const item of $input.all()) {
  const p = item.json;
  if (vistos.has(p.place_id)) continue; // mesmo lugar em duas páginas da busca
  vistos.add(p.place_id);

  const classificacao = lerClassificacao(p.classificacao);
  const cidade = p.cidade || cidadeDoEndereco(p.endereco);
  const instagramGoogle = instagramDoLink(p.rede_social);

  let slug = slugify(p.nome) || slugify(p.place_id);
  if (slugsEmUso.has(slug) && cidade) slug = slug + '-' + slugify(cidade);
  const base = slug;
  for (let n = 2; slugsEmUso.has(slug); n++) slug = base + '-' + n;
  slugsEmUso.add(slug);

  const briefing = (p.content?.parts ?? []).map(parte => parte.text ?? '').join('').trim()
    || 'Sem avaliações em texto para resumir.';

  const lead = {
    place_id: p.place_id,
    nome: p.nome,
    slug,
    vertical: String(classificacao.vertical || p.tipo || '').trim().toLowerCase(),
    cidade,
    endereco: p.endereco,
    telefone: p.telefone,
    instagram: instagramGoogle || p.instagram_busca || '',
    nota: p.rating ?? '',
    avaliacoes: p.userRatingCount,
    maps_url: p.googleMapsUri ?? '',
    status: 'novo',
    score: p.score,
    criado_em: agora,
    briefing,
    fotos_places: (p.photos ?? []).slice(0, 5).map(foto => foto.name).filter(Boolean),
  };

  const linhaInstagram = instagramGoogle
    || (p.instagram_busca ? p.instagram_busca + ' (achado na busca do Caçador, não no Google Maps — confirmar à mão)' : 'não informado pelo Google — confirmar à mão');

  lead.content_md = [
    '# ' + lead.nome,
    '',
    '- **Vertical:** ' + lead.vertical,
    '- **Cidade:** ' + lead.cidade,
    '- **País:** ' + (p.pais || 'não informado'),
    '- **Endereço:** ' + lead.endereco,
