3.2,"position":[5170,280],"parameters":{"mode":"combine","combineBy":"combineByPosition","options":{}}},{"id":"6cde3114-50fe-477b-a366-442556f14c94","name":"Portão","notes":"Corta o que não é lead antes de gastar HTTP e Gemini. Nada daqui vai para a planilha: é barato reavaliar na próxima rodada.","type":"n8n-nodes-base.code","typeVersion":2,"position":[3300,-250],"parameters":{"mode":"runOnceForAllItems","language":"javaScript","jsCode":"// Portão: corta o que não é lead antes de gastar HTTP e Gemini.
// Casos reais que motivaram cada regra estão no registro.md (16-17/09/2026).
const SEIS_MESES = 183 * 24 * 60 * 60 * 1000;
const agora = Date.now();
const saida = [];

$input.all().forEach((item, i) => {
  const p = item.json;

  // Fechado temporária ou permanentemente no Google
  if (p.businessStatus && p.businessStatus !== 'OPERATIONAL') return;

  // Nota baixa: site não resolve o problema desse negócio
  if (Number(p.rating ?? 0) < 4) return;

  // Ninguém avalia há 6 meses: parado ou fechado sem avisar o Google (Estação do Pet)
  const datas = (p.reviews ?? []).map(r => Date.parse(r.publishTime)).filter(Number.isFinite);
  const ultima = datas.length ? Math.max(...datas) : null;
  if (ultima && agora - ultima > SEIS_MESES) return;

  // Ficha de captação: 0800/toll-free + endereço residencial + poucas avaliações (CareCrafters)
  const tel = String(p.telefone ?? '').replace(/\D/g, '');
  const tollFree = /^(18(00|33|44|55|66|77|88)|550?800)/.test(tel);
  const residencial = /\b(apt|apto|apartamento|unit)\b/i.test(String(p.endereco ?? ''));
  if (tollFree && residencial && p.userRatingCount < 10) return;

  saida.push({ json: { ...p, ultima_avaliacao: ultima ? new Date(ultima).toISOString() : '' }, pairedItem: i });
});

return saida;
"}},{"id":"checar-site-proprio","name":"Checar site próprio","notes":"Até 3 rodadas, https e http, com e sem www (claude-ops/site-cacador-site-no-ar.js). Site no ar vai para a planilha como descartado; fora do ar segue com o +40.","type":"n8n-nodes-base.code","typeVersion":2,"position":[3520,-250],"parameters":{"mode":"runOnceForAllItems","language":"javaScript","jsCode":"// Checar site próprio (01 · Caçador): quem tem site no ar não vira pasta.
// Até 07/10/2026 era UM GET de 10 s na raiz do domínio. 74 leads ganharam o +40
