const ALTA_INTENCAO = ["desentup", "dedetiz", "pragas", "cacamba", "contab", "contador", "advoc", "advog", "usinag", "caldeir", "metalurg", "andaime", "locacao de equip", "locadora", "reforma", "engenhar", "construtora"];
const DIA = 24 * 60 * 60 * 1000;
const agora = Date.now();

function lerClassificacao(texto) {
  const s = String(texto ?? '');
  try {
    return JSON.parse(s.slice(s.indexOf('{'), s.lastIndexOf('}') + 1));
  } catch (e) {
    return null;
  }
}

function normalizar(texto) {
  return String(texto ?? '').toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '').replace(/[^a-z0-9]+/g, ' ').trim();
}

// Celular é o que tem WhatsApp e cai na mão de uma pessoa, não da recepção.
// Brasil: 55 + DDD + 9 + 8 dígitos. Portugal: 351 + 9 + 8 dígitos.
// Outros países: não dá para saber pelo número, fica null (não pontua nem bloqueia).
function tipoDeTelefone(bruto, pais) {
  const d = String(bruto ?? '').replace(/\D/g, '');
  const p = normalizar(pais);
  if (p === 'brasil' || p === 'brazil' || d.indexOf('55') === 0) {
    const local = d.indexOf('55') === 0 ? d.slice(2) : d;
    if (local.length === 11 && local[2] === '9') return 'celular';
    return 'fixo';
  }
  if (p === 'portugal' || d.indexOf('351') === 0) {
    const local = d.indexOf('351') === 0 ? d.slice(3) : d;
    return local[0] === '9' ? 'celular' : 'fixo';
  }
  return null;
}

const saida = [];

$input.all().forEach((item, i) => {
